def native_md(t):
    m = re.search(r'## Native record\s*\n(.*?)(?=\n## |\Z)', t, re.S)
    return m.group(1).strip() if m else None

def native_txt(t):
    parts = t.split('NATIVE RECORD')
    if len(parts) >= 3:
        seg = parts[2]
        m = re.match(r'\s*\n(.*?)\n\s*\n[A-Z]', seg, re.S)
        if m: return m.group(1).strip()
        # fallback: up to RELIANCE
        m2 = re.search(r'\n(.*?)\nRELIANCE', seg, re.S)
        return m2.group(1).strip() if m2 else seg[:400]
    return None

def native_eml(t):
    m = re.search(r'NATIVE RECORD\s*\n(.*?)\nRELIANCE', t, re.S)
    return m.group(1).strip() if m else None

def native_csv(t):
    lines = t.splitlines()
    import csv as _csv, io
    rdr = _csv.DictReader(io.StringIO(t))
    for r in rdr:
        if r.get('row_type') == 'metadata' and r.get('key') == 'body':
            return r.get('value')
    return None

