    m = re.search(r'<native-record>(.*?)</native-record>', t, re.S)
    return m.group(1).strip() if m else None

def native_html(t):
    m = re.search(r'</dl><p>(.*?)</p>', t, re.S)
    return m.group(1).strip() if m else None

def native_pdf(t):
