    try:
        import zlib
        out = []
        for m in re.finditer(rb'stream\r?\n(.*?)endstream', t.encode('latin-1'), re.S):
            try:
                out.append(zlib.decompress(m.group(1)).decode('latin-1'))
            except Exception:
                out.append(m.group(1).decode('latin-1'))
        return "\n".join(out)[:3000]
